  url: string | null;
  replies: number | null;
  reposts: number | null;
  likes: number | null;
  views: number | null;
}

/**
 * 页面内提取脚本。
 *
 * 必须短：CDP `Runtime.evaluate` 在扩展侧有 5 秒硬超时，跑不完就整条命令失败。
 * 交互数从 `div[role="group"]` 的 aria-label 里取（"34 replies, 12 reposts, 331 likes, 52
