+  it("开后台标签页 → 取第一个答案全文 → 关标签页", async () => {
+    const { bridge, calls } = answerBridge(ANSWER);
+
+    const outcome = await fetchZhihuAnswer(URL, { bridge, waitMs: 1_000 });
+    expect(outcome).toEqual({ ok: true, url: URL, text: ANSWER });
+
+    expect(calls[0]?.action).toBe("tab.new");
+    expect(calls[0]?.params).toEqual({ url: URL, groupTitle: "daily.news" });
+    expect(calls.at(-1)?.action).toBe("tab.close");
+    expect(calls.at(-1)?.params).toEqual({ targetId: 42 });
+  });
+
+  it("提取表达式只认 .RichText，且只取第一个答案", async () => {
+    const { bridge, calls } = answerBridge(ANSWER);
+    await fetchZhihuAnswer(URL, { bridge, waitMs: 1_000 });
+
+    const expressions = calls
+      .filter((call) => call.action === "page.evaluate")
+      .map((call) => String(call.params.expression));
+    expect(expressions.length).toBeGreaterThan(0);
+    for (const expression of expressions) {
+      expect(expression).toContain(".RichText");
+      expect(expression).toContain("innerText");
+    }
+  });
+
+  it("答案还没渲染出来时先等（每 1s 探一次）", async () => {
+    let polls = 0;
+    const { bridge } = answerBridge(() => {
+      polls += 1;
+      return polls < 3 ? "" : ANSWER;
+    });
+
+    const outcome = await fetchZhihuAnswer(URL, { bridge, waitMs: 5_000 });
+    expect(outcome.ok).toBe(true);
+    expect(polls).toBe(3);
