+    expect(calls.some((call) => call.action === "tab.close")).toBe(false);
+  });
+
+  it("关标签页失败不影响返回值", async () => {
+    const { bridge } = stubBridge((action) => {
+      if (action === "tab.new") {
+        return { tab: { id: 42 } };
+      }
+      if (action === "tab.close") {
