+    const outcome = await fetchZhihuAnswer(URL, { bridge, waitMs: 1_000 });
+    expect(outcome).toEqual({ ok: true, url: URL, text: ANSWER });
+  });
+
+  it("page.evaluate 抛错按「没有内容」处理，继续等", async () => {
+    let calls = 0;
+    const { bridge } = stubBridge((action) => {
+      if (action === "tab.new") {
+        return { tab: { id: 42 } };
+      }
+      if (action === "tab.close") {
+        return { ok: true };
+      }
+      calls += 1;
+      if (calls === 1) {
