+    const outcome = await fetchZhihuAnswer(URL, { bridge, waitMs: 1_000 });
+    expect(outcome).toEqual({ ok: false, reason: expect.stringContaining("Chrome 扩展没有在轮询") });
+    expect(calls).toEqual([]);
+  });
+
+  it("自己 connect 出来的桥用完 stop，不让它长期占着端口", async () => {
+    const { bridge } = answerBridge(ANSWER);
+    let stopped = 0;
+    (bridge as unknown as { stop: () => Promise<void> }).stop = async () => {
+      stopped += 1;
+    };
+
+    const connectSpy = spyOn(ChromeBridge, "connect").mockResolvedValue(bridge);
+    try {
+      const outcome = await fetchZhihuAnswer(URL, { waitMs: 1_000 });
+      expect(outcome.ok).toBe(true);
+    } finally {
+      connectSpy.mockRestore();
+    }
+    expect(stopped).toBe(1);
+  });
+
+  it("注入的桥不 stop（不归调用方管）", async () => {
+    const { bridge } = answerBridge(ANSWER);
+    let stopped = 0;
+    (bridge as unknown as { stop: () => Promise<void> }).stop = async () => {
+      stopped += 1;
+    };
+
+    const outcome = await fetchZhihuAnswer(URL, { bridge, waitMs: 1_000 });
+    expect(outcome.ok).toBe(true);
+    expect(stopped).toBe(0);
+  });
+});
