    }
    return this.dispatch(action, params, timeoutMs);
  }

  /** client 模式：把命令转给占着端口的 owner。 */
  private async sendViaOwner(
    action: string,
    params: Record<string, unknown>,
    timeoutMs: number,
  ): Promise<unknown> {
