+
+/**
+ * 把每条问题的第一个答案全文抓下来。
+ *
+ * - 串行抓：Chrome 里并发开多个标签页会互相抢焦点 / 抢渲染，收益是负的；
+ * - 采纳条件：够长（≥ `MIN_ANSWER_CHARS`）**且**比摘要片段长。第二个条件防的是
+ *   「登录提示 / 折叠占位 / 只有标题的壳」——它们可能过 200 字，却比摘要还短；
+ * - 抓不到或没有链接：原样返回，正文仍是摘要片段；每条一条 info 日志，整批不抛错。
+ */
+export async function expandZhihu(items: ZhihuItem[], deps: ExpandZhihuDeps = {}): Promise<ZhihuItem[]> {
+  if (deps.fetchAnswer !== undefined) {
+    return expandZhihuSerially(items, deps.fetchAnswer);
+  }
+
+  // 默认路径：整批只 connect 一次、末尾 stop 一次。逐条起停每一条都要重新等扩展轮询。
+  let bridge: ChromeBridge;
+  try {
+    bridge = await ChromeBridge.connect();
+  } catch (error) {
+    const reason = `连不上 Chrome 桥：${error instanceof Error ? error.message : String(error)}`;
+    logger.warn("zhihu bridge failed", { items: items.length, reason });
+    return expandZhihuSerially(items, async () => ({ ok: false, reason }));
+  }
+
+  try {
+    return await expandZhihuSerially(items, (url) => fetchZhihuAnswer(url, { bridge }));
+  } finally {
+    await bridge.stop();
+  }
+}
+
+/** 逐条串行抓。 */
+async function expandZhihuSerially(
+  items: ZhihuItem[],
+  fetchAnswer: (url: string) => Promise<ZhihuAnswerOutcome>,
+): Promise<ZhihuItem[]> {
+  const expanded: ZhihuItem[] = [];
