+    const outcome = await fetchZhihuAnswer(URL, { bridge, waitMs: 1_000, extensionWaitMs: 200 });
+    expect(outcome).toEqual({ ok: false, reason: expect.stringContaining("Chrome 扩展没有在轮询") });
+    expect(calls).toEqual([]);
+  });
+
+  it("新建 owner 桥时先有界等待扩展轮询，等到了才开标签页", async () => {
+    // 新建 owner 桥在扩展下一次 /next 之前 status().connected 恒为 false
+    let statusCalls = 0;
+    const { bridge, calls } = stubBridge(
+      (action) => {
+        if (action === "tab.new") {
+          return { tab: { id: 42 } };
+        }
+        if (action === "tab.close") {
+          return { ok: true };
+        }
+        return ANSWER;
+      },
+      {
+        connected: () => {
+          statusCalls += 1;
+          return statusCalls >= 3;
+        },
+      },
+    );
+
+    const outcome = await fetchZhihuAnswer(URL, { bridge, waitMs: 1_000 });
+    expect(outcome).toEqual({ ok: true, url: URL, text: ANSWER });
+    expect(statusCalls).toBe(3);
+    // 等待期间不发任何命令：第一条命令就是 tab.new
+    expect(calls[0]?.action).toBe("tab.new");
+    expect(calls.filter((call) => call.action === "tab.new")).toHaveLength(1);
+  });
