interface PendingCommand {
  resolve: (value: unknown) => void;
  reject: (error: Error) => void;
  timer: ReturnType<typeof setTimeout>;
  /** 命令已经被扩展取走的时刻。用来区分「没人轮询」与「扩展没回结果」。 */
  deliveredAt?: number;
}

export interface ChromeBridgeOptions {
  host?: string;
  port?: number;
  /** 扩展长轮询的最长等待。 */
  pollTimeoutMs?: number;
  /** 探测已有 owner 的超时。 */
