/** 桥监听地址。扩展把地址写死成这个端口，换不了。 */
export const BRIDGE_HOST = "127.0.0.1";
export const BRIDGE_PORT = 17318;

/** 桥的根地址。 */
export const BRIDGE_URL = `http://${BRIDGE_HOST}:${BRIDGE_PORT}`;

/** 扩展长轮询的最长等待。与扩展侧的 25s 对齐。 */
